using namespace std;
int main(){
    int n, m;
    cin >> n >> m;
    vector<int> a(m);
    for (auto &x : a) cin >> x;
    int h = n / 2;                       // no album may take more than floor(n/2) slots (circular)
    vector<int> c(m);
    long long tot = 0;
    for (int i = 0; i < m; i++) { c[i] = min(a[i], h); tot += c[i]; }
    if (tot < n) { cout << -1 << "\n"; return 0; }
    long long ex = tot - n;              // shrink counts down to exactly n
    for (int i = 0; i < m && ex > 0; i++) {
        long long d = min<long long>(ex, c[i]);
        c[i] -= d; ex -= d;
    }
    vector<int> ord(m);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return c[x] > c[y]; });
    vector<int> slot;                    // fill even positions first, then odd
    for (int i = 0; i < n; i += 2) slot.push_back(i);
    for (int i = 1; i < n; i += 2) slot.push_back(i);
    vector<int> res(n);
    int k = 0;
    for (int id : ord)
        for (int t = 0; t < c[id]; t++) res[slot[k++]] = id + 1;
    for (int i = 0; i < n; i++) cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

