using namespace std;
int main(){
    int n,k,m,a; cin>>n>>k>>m>>a;
    vector<int> v(n+1,0), last(n+1,0);
    for(int j=1;j<=a;j++){int g; cin>>g; v[g]++; last[g]=j;}
    int r=m-a;
    vector<int> res(n+1,3);
    auto ahead=[&](int j,int vi,int li){ return v[j]>vi || (v[j]==vi && v[j]>0 && last[j]<li); };
    for(int i=1;i<=n;i++){
        if(v[i]>0){                               // can i be pushed out by the remaining votes?
            int A=0; vector<long long> need;
            for(int j=1;j<=n;j++){ if(j==i) continue;
                if(ahead(j,v[i],last[i])) A++; else need.push_back(v[i]-v[j]+1); }
            sort(need.begin(),need.end());
            bool adv = A>=k;
            if(!adv && (int)need.size()>=k-A){ long long s=0; for(int t=0;t<k-A;t++) s+=need[t]; adv = s<=r; }
            if(!adv){ res[i]=1; continue; }
        }
        int vi=v[i]+r; if(vi==0) continue;        // best case: all remaining votes go to i
        int li = r>0 ? m+1 : last[i];
        int cnt=0; for(int j=1;j<=n;j++) if(j!=i && ahead(j,vi,li)) cnt++;
        if(cnt<k) res[i]=2;
    }
    for(int i=1;i<=n;i++) cout<<res[i]<<(i<n?' ':'\n');
}

