using namespace std;
int main(){
    string s;
    cin >> s;
    int n = s.size();
    const int INF = INT_MAX;
    vector<int> L(n), R(n), tm(n, INF);
    for (int i = 0; i < n; i++) { L[i] = i - 1; R[i] = i + 1; }
    queue<int> q;
    for (int i = 0; i < n; i++) {
        bool d = (i > 0 && s[i - 1] != s[i]) || (i + 1 < n && s[i + 1] != s[i]);
        if (d) { tm[i] = 1; q.push(i); }
    }
    int ans = 0;
    while (!q.empty()) {
        int x = q.front(); q.pop();
        int t = tm[x];
        ans = max(ans, t);
        int l = L[x], r = R[x];          // unlink x
        if (l >= 0) R[l] = r;
        if (r < n) L[r] = l;
        if (l >= 0 && r < n && s[l] != s[r]) {
            // a survivor adjacent to a node deleted at the same step is handled when that node pops
            if (tm[l] == INF && tm[r] > t) { tm[l] = t + 1; q.push(l); }
            if (tm[r] == INF && tm[l] > t) { tm[r] = t + 1; q.push(r); }
        }
    }
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n, m, r, k;
    cin >> n >> m >> r >> k;
    auto cnt = [&](long long x, long long len) {
        return min({x, len - x + 1, r, len - r + 1});
    };
    vector<long long> R(n), C(m);
    for (long long i = 1; i <= n; i++) R[i - 1] = cnt(i, n);
    for (long long j = 1; j <= m; j++) C[j - 1] = cnt(j, m);
    sort(R.rbegin(), R.rend());
    sort(C.rbegin(), C.rend());
    // k largest products R[i]*C[j] in a matrix that is sorted in both directions
    priority_queue<tuple<long long, int, int>> pq;
    set<pair<int, int>> seen;
    pq.push({R[0] * C[0], 0, 0});
    seen.insert({0, 0});
    long long sum = 0;
    for (long long t = 0; t < k; t++) {
        auto [p, i, j] = pq.top(); pq.pop();
        sum += p;
        if (i + 1 < n && !seen.count({i + 1, j})) {
            seen.insert({i + 1, j});
            pq.push({R[i + 1] * C[j], i + 1, j});
        }
        if (j + 1 < m && !seen.count({i, j + 1})) {
            seen.insert({i, j + 1});
            pq.push({R[i] * C[j + 1], i, j + 1});
        }
    }
    double T = (double)(n - r + 1) * (double)(m - r + 1);
    printf("%.10f\n", (double)sum / T);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, a, b;
    cin >> n >> a >> b;
    vector<long long> hp(n), dm(n);
    long long base = 0;
    for (int i = 0; i < n; i++) { cin >> hp[i] >> dm[i]; base += dm[i]; }
    if (b == 0) { cout << base << "\n"; return 0; }
    vector<long long> g(n);
    for (int i = 0; i < n; i++) g[i] = max(0LL, hp[i] - dm[i]);
    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return g[x] > g[y]; });
    vector<int> pos(n);
    vector<long long> P(n + 1, 0);
    for (int r = 0; r < n; r++) { pos[ord[r]] = r; P[r + 1] = P[r] + g[ord[r]]; }
    // sum of the top k gains among creatures other than j
    auto topEx = [&](int j, int k) -> long long {
        if (k <= 0) return 0;
        if (k >= n - 1) return P[n] - g[j];
        if (pos[j] < k + 1) return P[k + 1] - g[j];
        return P[k];
    };
    // all doublings go to one copied creature (convexity), others take best gains
    long long best = 0;
    for (int j = 0; j < n; j++)
        for (int t = 0; t <= a; t++) {
            long long withJ = (hp[j] << t) - dm[j] + topEx(j, b - 1);
            long long without = topEx(j, b);
            best = max(best, max(withJ, without));
        }
    cout << base + best << "\n";
    return 0;
}

