int main(){
    string s;
    cin >> s;
    int L = s.size();
    long long best = LLONG_MAX;
    const char* ends[4] = {"00", "25", "50", "75"};
    for (auto e : ends)
        for (int i = 0; i < L; i++) {
            if (s[i] != e[0]) continue;
            for (int j = 0; j < L; j++) {
                if (j == i || s[j] != e[1]) continue;
                vector<int> ord;              // final order of original indices
                for (int k = 0; k < L; k++) if (k != i && k != j) ord.push_back(k);
                ord.push_back(i);
                ord.push_back(j);
                if (s[ord[0]] == '0') continue; // no leading zero
                long long inv = 0;            // adjacent swaps = inversions
                for (int x = 0; x < L; x++)
                    for (int y = x + 1; y < L; y++)
                        if (ord[x] > ord[y]) inv++;
                best = min(best, inv);
            }
        }
    cout << (best == LLONG_MAX ? -1 : best) << "\n";
    return 0;
}

