    for (int l = 1; l <= k; l++) cin >> a[l];
    vector<int> lf(n, -1);                 // last free position <= p
    for (int p = 0; p < n; p++) lf[p] = blk[p] ? (p > 0 ? lf[p - 1] : -1) : p;
    long long best = LLONG_MAX;
    for (int l = 1; l <= k; l++) {
        long long cnt = 0, cur = 0;        // units [0, cur) are lit
        bool ok = true;
        while (cur < n) {
            int x = lf[cur];               // farthest free start that still covers unit cur
            if (x < 0 || x + l <= cur) { ok = false; break; }
            cur = x + l;
            cnt++;
        }
        if (ok) best = min(best, cnt * a[l]);
    }
    cout << (best == LLONG_MAX ? -1 : best) << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    const long long MOD = 1000000007LL;
    long long n, x, y;
    cin >> n >> x >> y;
    vector<pair<long long, long long>> sh(n);
    for (auto &p : sh) cin >> p.first >> p.second;   // (l, r)
    sort(sh.begin(), sh.end());
    multiset<long long> ends;                         // last end time of each open TV
    long long ans = 0;
    for (auto [l, r] : sh) {
        ans = (ans + y % MOD * ((r - l) % MOD)) % MOD;
        bool linked = false;
        auto it = ends.lower_bound(l);                // first end >= l
        if (it != ends.begin()) {
            --it;                                     // largest end < l
            long long gap = l - *it;
            if (y * gap < x) {                        // extending that TV is cheaper than a new TV
                ans = (ans + y * gap % MOD) % MOD;
                ends.erase(it);
                linked = true;
            }
        }
        if (!linked) ans = (ans + x % MOD) % MOD;
        ends.insert(r);
    }
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int M; vector<long long> capT, costT, prc;
void setp(int nd,int lo,int hi,int pos,long long c){
    if(lo==hi){ capT[nd]=c; costT[nd]=c*prc[lo]; return; }
    int mid=(lo+hi)/2;
    if(pos<=mid) setp(2*nd,lo,mid,pos,c); else setp(2*nd+1,mid+1,hi,pos,c);
    capT[nd]=capT[2*nd]+capT[2*nd+1]; costT[nd]=costT[2*nd]+costT[2*nd+1];
}
// cost of the cheapest `need` units among active plans
long long take(int nd,int lo,int hi,long long &need){
    if(need<=0||capT[nd]==0) return 0;
    if(capT[nd]<=need){ need-=capT[nd]; return costT[nd]; }
    if(lo==hi){ long long r=need*prc[lo]; need=0; return r; }
    int mid=(lo+hi)/2;
    long long r=take(2*nd,lo,mid,need);
    return r+take(2*nd+1,mid+1,hi,need);
}
int main(){
    int n,m; long long k; cin>>n>>k>>m;
    vector<long long> L(m),R(m),C(m),P(m);
    for(int i=0;i<m;i++) cin>>L[i]>>R[i]>>C[i]>>P[i];
    vector<int> ord(m); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){ return P[a]<P[b]; });
    vector<int> rk(m); M=m; prc.assign(M,0);
    for(int r=0;r<M;r++){ rk[ord[r]]=r; prc[r]=P[ord[r]]; }
    capT.assign(4*M+4,0); costT.assign(4*M+4,0);
    vector<vector<int>> addAt(n+2), remAt(n+2);
    for(int i=0;i<m;i++){ addAt[L[i]].push_back(i); remAt[R[i]+1].push_back(i); }
    long long ans=0;
    for(int d=1;d<=n;d++){
        for(int i:remAt[d]) setp(1,0,M-1,rk[i],0);
        for(int i:addAt[d]) setp(1,0,M-1,rk[i],C[i]);
        long long need=k; ans+=take(1,0,M-1,need);
    }
    cout<<ans<<"\n";
}

