int main(){
    long long t, n, a, b, k;
    cin >> t >> n >> a, cin >> b >> k;
    long long O = (n + 1) / 2, E = n / 2;      // odd lectures use room a, even use room b
    long long lo = max(0LL, k - E), hi = min(k, O);
    if (k > n || lo > hi) { cout << 0 << "\n"; return 0; }
    // p students can all pass iff p*lo <= O*a and p*k - min(p*hi, O*a) <= E*b
    auto ok = [&](long long p) {
        if (p * lo > O * a) return false;
        return p * k - min(p * hi, O * a) <= E * b;
    };
    long long l = 0, r = t;
    while (l < r) {
        long long mid = (l + r + 1) / 2;
        if (ok(mid)) l = mid; else r = mid - 1;
    }
    cout << l << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m; cin>>n>>m;
    vector<vector<int>> adj(n+1);
    for(int i=0;i<m;i++){ int v,u; cin>>v>>u; adj[v].push_back(u); adj[u].push_back(v); }
    vector<int> comp(n+1,0), dist(n+1), par(n+1);
    auto bfs=[&](int s){                          // BFS from s; returns a farthest node
        vector<int> q{s}; dist[s]=0; par[s]=0;
        for(size_t h=0;h<q.size();h++){ int u=q[h];
            for(int v:adj[u]) if(v!=par[u]){ par[v]=u; dist[v]=dist[u]+1; q.push_back(v); } }
        int far=s; for(int v:q) if(dist[v]>dist[far]) far=v;
        return far;
    };
    struct C{ int r,center,diam; };
    vector<C> cs;
    for(int s=1;s<=n;s++){
        if(comp[s]) continue;
        int u=bfs(s);
        vector<int> stk{s}; comp[s]=1;
        for(size_t h=0;h<stk.size();h++) for(int v:adj[stk[h]]) if(!comp[v]){ comp[v]=1; stk.push_back(v); }
        int v=bfs(u), D=dist[v], c=v;
        for(int t=0;t<D-D/2;t++) c=par[c];        // node at distance D/2 from u (tree center)
        cs.push_back({(D+1)/2, c, D});
    }
    sort(cs.begin(),cs.end(),[](const C&a,const C&b){ return a.r>b.r; });
    long long diam=0;
    for(auto&x:cs) diam=max<long long>(diam,x.diam);
    if(cs.size()>=2) diam=max<long long>(diam,cs[0].r+cs[1].r+1);
    if(cs.size()>=3) diam=max<long long>(diam,cs[1].r+cs[2].r+2);
    cout<<diam<<"\n";
    for(size_t i=1;i<cs.size();i++) cout<<cs[i].center<<" "<<cs[0].center<<"\n";
}

