int main(){
    int n;
    cin >> n;
    const int MAXV = 200005;
    vector<int> a(n);
    vector<long long> cnt(MAXV + 2, 0);
    for (auto &v : a) { cin >> v; cnt[v]++; }
    vector<long long> P(MAXV + 2, 0);
    for (int v = 1; v <= MAXV + 1; v++) P[v] = P[v - 1] + cnt[v];
    // nxt[v] = smallest j > v with cnt[j] < 2 (cnt 0 or 1)
    vector<int> nxt(MAXV + 3, MAXV + 1);
    for (int v = MAXV; v >= 0; v--) {
        nxt[v] = (cnt[v + 1] < 2) ? v + 1 : nxt[v + 1];
    }
    long long best = -1; int bl = 1, br = 1;
    for (int l = 1; l <= MAXV; l++) {
        if (cnt[l] == 0) continue;
        int j = nxt[l];
        int r = (j <= MAXV && cnt[j] == 1) ? j : j - 1;
        if (r < l) r = l;
        long long s = P[r] - P[l - 1];
        if (s > best) { best = s; bl = l; br = r; }
    }
    cout << best << "\n";
    // circle: one copy of each value ascending, then the remaining copies descending
    vector<int> circ;
    for (int v = bl; v <= br; v++) circ.push_back(v);
    for (int v = br; v >= bl; v--) for (long long t = 0; t < cnt[v] - 1; t++) circ.push_back(v);
    for (size_t i = 0; i < circ.size(); i++) cout << circ[i] << (i + 1 < circ.size() ? ' ' : '\n');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// Binary search on T. Cheap copies of type i go on its last sale day <= T, the rest cost 2 on day T.
// Feasible iff greedy cheap counts x_i keep prefix caps (sum of x over ld<=d is <= d) and sum x >= 2K-T.
vector<long long> mn, lz;
void build(int nd,int lo,int hi){ lz[nd]=0; if(lo==hi){ mn[nd]=lo; return; }
    int mid=(lo+hi)/2; build(2*nd,lo,mid); build(2*nd+1,mid+1,hi); mn[nd]=min(mn[2*nd],mn[2*nd+1]); }
void add(int nd,int lo,int hi,int l,int r,long long v){
    if(r<lo||hi<l) return;
    if(l<=lo&&hi<=r){ mn[nd]+=v; lz[nd]+=v; return; }
    int mid=(lo+hi)/2; add(2*nd,lo,mid,l,r,v); add(2*nd+1,mid+1,hi,l,r,v);
    mn[nd]=min(mn[2*nd],mn[2*nd+1])+lz[nd]; }
long long qry(int nd,int lo,int hi,int l,int r){
    if(r<lo||hi<l) return LLONG_MAX/4;
    if(l<=lo&&hi<=r) return mn[nd];
    int mid=(lo+hi)/2;
    return min(qry(2*nd,lo,mid,l,r),qry(2*nd+1,mid+1,hi,l,r))+lz[nd]; }
int main(){
    int n,m; cin>>n>>m;
    vector<long long> K(n); long long K2=0;
    for(auto&k:K){ cin>>k; K2+=k; }
    vector<vector<int>> s(n);
    for(int j=0;j<m;j++){ int d,t; cin>>d>>t; s[t-1].push_back(d); }
    for(auto&v:s) sort(v.begin(),v.end());
    auto feas=[&](int t){
        build(1,1,t); long long tot=0;
        for(int i=0;i<n;i++){
            auto it=upper_bound(s[i].begin(),s[i].end(),t);
            if(it==s[i].begin()) continue;          // no sale on or before T
            int ld=*prev(it);
            long long x=min(K[i],qry(1,1,t,ld,t));
            if(x>0){ add(1,1,t,ld,t,-x); tot+=x; }
        }
        return tot>=2*K2-t; };
    int lo=1, hi=(int)min<long long>(2*K2,400005);
    mn.assign(4*hi+8,0); lz.assign(4*hi+8,0);
    while(lo<hi){ int mid=(lo+hi)/2; if(feas(mid)) hi=mid; else lo=mid+1; }
    cout<<lo<<"\n";
}

