int n; long long k;
vector<long long> a, P;               // sorted values, prefix sums
// min cost to bring every value into the window [L, L+D]
long long costAt(long long L, long long D) {
    int c1 = lower_bound(a.begin(), a.end(), L) - a.begin();          // a_i < L
    long long cost1 = (long long)c1 * L - P[c1];
    long long H = L + D;
    int i2 = upper_bound(a.begin(), a.end(), H) - a.begin();          // a_i > H
    long long cost2 = (P[n] - P[i2]) - (long long)(n - i2) * H;
    return cost1 + cost2;
}
long long minCost(long long D) {
    // costAt is convex in L; find the smallest L where the next step is non-negative
    long long lo = 1, hi = 1000000000LL;
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        if (costAt(mid + 1, D) - costAt(mid, D) >= 0) hi = mid; else lo = mid + 1;
    }
    return costAt(lo, D);
}
int main(){
    cin >> n >> k;
    a.resize(n);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    P.assign(n + 1, 0);
    for (int i = 0; i < n; i++) P[i + 1] = P[i] + a[i];
    long long lo = 0, hi = a[n - 1] - a[0];
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        if (minCost(mid) <= k) hi = mid; else lo = mid + 1;
    }
    cout << lo << "\n";
    return 0;
}

