// beauty = number of cyclic shifts that are correct bracket sequences
// = number of prefix positions attaining the minimum balance (if the total balance is 0)
long long beauty(const string &s) {
    int n = s.size(), bal = 0, mn = 0;
    long long cnt = 0;
    vector<int> pre(n + 1, 0);
    for (int i = 0; i < n; i++) { bal += (s[i] == '(' ? 1 : -1); pre[i + 1] = bal; }
    if (bal != 0) return 0;
    mn = *min_element(pre.begin(), pre.begin() + n);
    for (int i = 0; i < n; i++) if (pre[i] == mn) cnt++;
    return cnt;
}
int main(){
    int n; string s;
    cin >> n >> s;
    long long best = beauty(s);
    int bl = 1, br = 1;
    for (int l = 0; l < n; l++)
        for (int r = l + 1; r < n; r++) {
            if (s[l] == s[r]) continue;
            swap(s[l], s[r]);
            long long b = beauty(s);
            if (b > best) { best = b; bl = l + 1; br = r + 1; }
            swap(s[l], s[r]);
        }
    cout << best << "\n" << bl << " " << br << "\n";
    return 0;
}

