#include <bits/stdc++.h>
using namespace std;
// Upper-triangle ops (x<y) are forced cell by cell: scanning row x and columns y descending,
// op(x,y) = A(x,y) ^ rowPar ^ colPar[y]. Lower-triangle ops are the same on the transpose.
// Each op toggles diagonal cells x and y; leftover diagonal ones need one single-cell op each.
int main(){
    int n;
    cin >> n;
    vector<string> g(n);
    for (auto &s : g) cin >> s;
    // line i (0-based) is row i+1 (matches the sample), A[r][c] for 1-based r,c
    auto A = [&](int r, int c) { return g[r - 1][c - 1] - '0'; };
    vector<int> diag(n + 2, 0);
    long long ans = 0;
    for (int pass = 0; pass < 2; pass++) {
        vector<int> colPar(n + 2, 0);
        for (int x = 1; x <= n; x++) {
            int rowPar = 0;
            for (int y = n; y > x; y--) {
                int a = pass == 0 ? A(x, y) : A(y, x);      // lower pass reads the transpose
                int op = a ^ rowPar ^ colPar[y];
                if (op) {
                    ans++;
                    rowPar ^= 1; colPar[y] ^= 1;
                    diag[x] ^= 1; diag[y] ^= 1;
                }
            }
        }
    }
    for (int i = 1; i <= n; i++) if (A(i, i) ^ diag[i]) ans++;
    cout << ans << "\n";
    return 0;
}

