        long long G = 0, B = 0;
        for (int v = 2; v <= N; v++) {
            long long s = sz[v];
            G += pw[v] * (s % 2);                       // min: edge crossed iff subtree is odd
            B += pw[v] * min(s, (long long)N - s);      // max: edge crossed as often as possible
        }
        cout << G << " " << B << "\n";
    }
