#include <bits/stdc++.h>
using namespace std;
// Moves cost = sum of a * Manhattan distance; rows and columns separate, each optimal at a weighted median.
int n, m;
vector<long long> R, C;
long long wmedianCost(const vector<long long> &w) {
    int sz = w.size();
    long long W = 0;
    for (auto v : w) W += v;
    long long acc = 0; int med = 0;
    for (int i = 0; i < sz; i++) { acc += w[i]; if (2 * acc >= W) { med = i; break; } }
    long long cost = 0;
    for (int i = 0; i < sz; i++) cost += w[i] * llabs((long long)i - med);
    return cost;
}
int main(){
    int q;
    cin >> n >> m >> q;
    vector<vector<long long>> a(n, vector<long long>(m));
    R.assign(n, 0); C.assign(m, 0);
