        cin >> a[i][j]; R[i] += a[i][j]; C[j] += a[i][j];
    }
    cout << wmedianCost(R) + wmedianCost(C) << "\n";
    while (q--) {
        int x, y; long long z; cin >> x >> y >> z; x--; y--;
        long long d = z - a[x][y];
        a[x][y] = z; R[x] += d; C[y] += d;
